 }
 return ts.getPreEmitDiagnostics(ts.createProgram(roots,parsed.options,host)).map(d=>({
  file:d.file?relative(d.file.fileName):null,code:d.code,message:ts.flattenDiagnosticMessageText(d.messageText,' '),
